export const DR_HTML = "<!doctype html><html lang=\"he\" dir=\"rtl\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>תוכנית חירום · NuraWell</title><style>@page{size:A4;margin:14mm}\n*{box-sizing:border-box}\nbody{margin:0;font-family:\"Heebo\",\"Assistant\",\"Segoe UI\",Arial,sans-serif;color:#1d2340;line-height:1.65;background:linear-gradient(170deg,#e9edfb 0%,#efe9fb 55%,#e6f0fa 100%);-webkit-print-color-adjust:exact;print-color-adjust:exact}\n.page{max-width:820px;margin:0 auto;padding:30px 26px}\n.hero{border-radius:26px;padding:30px 28px;color:#eef4ea;background:radial-gradient(600px 260px at 90% 0,rgba(129,140,248,.55),transparent 60%),linear-gradient(135deg,#101a3a,#1c2b5e 60%,#14375a);box-shadow:0 18px 50px rgba(16,26,58,.25)}\n.hero h1{margin:0 0 6px;font-size:30px;letter-spacing:-.3px}\n.hero p{margin:0;color:#c7d2fe}\n.eyebrow{font-size:13px;font-weight:700;letter-spacing:.08em;color:#5eead4}\nh2{font-size:21px;margin:28px 0 10px;color:#1c2b5e;display:flex;align-items:center;gap:10px}\nh2 .n{width:30px;height:30px;border-radius:50%;display:inline-grid;place-items:center;font-size:15px;color:#eef4ea;background:linear-gradient(135deg,#0f766e,#4f46e5)}\n.card{background:rgba(231,238,220,.82);border:1px solid rgba(79,70,229,.16);border-radius:18px;padding:16px 18px;margin:10px 0;break-inside:avoid}\n.grid{display:grid;grid-template-columns:1fr 1fr;gap:0 12px;align-items:start}\n.pill{display:inline-block;padding:3px 10px;border-radius:999px;font-size:12.5px;font-weight:700;background:rgba(79,70,229,.12);color:#3730a3}\n.warn{background:linear-gradient(135deg,rgba(244,63,94,.10),rgba(244,114,182,.10));border-color:rgba(225,29,72,.25)}\n.ok{background:linear-gradient(135deg,rgba(13,148,136,.10),rgba(79,70,229,.08));border-color:rgba(13,148,136,.25)}\nol{padding-inline-start:22px;margin:6px 0}li{margin:5px 0}\ncode{font-family:ui-monospace,Consolas,monospace;direction:ltr;unicode-bidi:embed;background:rgba(28,43,94,.08);padding:1px 6px;border-radius:6px;font-size:13px}\ntable{width:100%;border-collapse:collapse}td,th{padding:8px 6px;border-bottom:1px solid rgba(28,43,94,.12);text-align:right;vertical-align:top}th{font-size:13px;color:#4b5580}\n.foot{margin-top:24px;font-size:12.5px;color:#5a6390;text-align:center}\n.brk{break-before:page}\n .page{padding:22px 22px} h2{margin:16px 0 6px;font-size:18px} .card{padding:11px 14px;margin:6px 0;font-size:13.5px} td,th{padding:5px 6px;font-size:13px} @media print{.page{zoom:.8;padding:0}}</style></head>\n<body><div class=\"page\">\n<div class=\"hero\"><div class=\"eyebrow\">דף אחד · להדפיס ולשמור ליד חלק שחזור 1</div><h1>אם משהו קורס: תוכנית החזרה לאוויר</h1><p>כל מה שצריך כדי שכל מפתח יחזיר את NuraWell לעבודה, גם בלי מי שבנה את המערכת.</p></div>\n\n<h2><span class=\"n\">1</span>איפה כל דבר נמצא</h2>\n<table>\n<tr><th>מה</th><th>איפה</th><th>הערה</th></tr>\n<tr><td>הקוד</td><td>GitHub · <code>danielsbhaucc-dot/NuraWell</code></td><td>הענף <code>main</code> הוא מה שבאוויר. ההוראות לכל מפתח נמצאות בקבצים <code>AI_CONTEXT.md</code> ו-<code>RULES.md</code>.</td></tr>\n<tr><td>האתר והשרתים</td><td>Vercel · הפרויקט NuraWell (פרנקפורט)</td><td>כל מיזוג ל-<code>main</code> עולה לאוויר לבד.</td></tr>\n<tr><td>מסד הנתונים</td><td>Supabase · פרויקט באירופה</td><td>בתוכנית החינמית אין גיבוי אוטומטי. לכן כל לילה בסביבות 03:30 נשמר גיבוי מלא ומוצפן (כולל המשתמשים) בתיקייה <code>backups/db/</code> באחסון הקבצים באירופה, ונשמרים 30 יום אחורה. אם הגיבוי נכשל, גדעון שולח התראה.</td></tr>\n<tr><td>הדומיין והמייל הנכנס</td><td>Cloudflare · <code>nurawell.ai</code></td><td>שם מוגדרים DNS, ניתוב הקבלות ודף 404.</td></tr>\n<tr><td>מייל יוצא</td><td>Resend</td><td>שולח מהכתובת no-reply@nurawell.ai.</td></tr>\n<tr><td>זיכרון של אלמוג</td><td>Upstash Vector (אירלנד)</td><td>אם המידע הזה אובד, אלמוג פשוט \"שוכח\". שום מידע של משתמשים לא נפגע.</td></tr>\n<tr><td>מפתחות ההצפנה</td><td>Vercel, במשתנים מוגנים, ובגיבוי המפתחות</td><td>סיסמה במנהל הסיסמאות · חלק 1 בכספת · חלק 2 במנהל הסיסמאות · חלק 3 אצל עורך הדין</td></tr>\n</table>\n\n<h2><span class=\"n\">2</span>מה עושים לפי סוג התקלה</h2>\n<div class=\"card\"><b>האתר לא עולה:</b> ב-Vercel, במסך Deployments, בוחרים את הגרסה האחרונה שעבדה ולוחצים Promote to Production. זה חוזר לאוויר תוך דקה.</div>\n<div class=\"card\"><b>חשבון השרת נמחק או ננעל:</b> יוצרים פרויקט Vercel חדש מאותו מאגר GitHub, ומעתיקים את כל משתני הסביבה. את המפתחות משחזרים לפי מדריך השחזור, ואת שאר המשתנים (מסד נתונים, מייל) מקבלים מחדש מהמסכים של כל שירות. בסוף מכוונים את הדומיין ב-Cloudflare לפרויקט החדש.</div>\n<div class=\"card\"><b>מידע במסד הנתונים נמחק או השתבש:</b> משחזרים מהגיבוי הלילי לפי סעיף 3 למטה (אם עוברים לתוכנית בתשלום, אפשר לשחזר גם במסך Database ואז Backups). לא משנים מפתחות, כי הם לא תלויים במסד.</div>\n<div class=\"card warn\"><b>חשד לפריצה:</b> כותבים לגדעון \"ניתוק מכל המכשירים\" (או מנתקים את כל המשתמשים ב-Supabase, במסך Authentication). אחר כך מחליפים סיסמאות ב-GitHub, ב-Vercel, ב-Supabase וב-Cloudflare, ופונים לעורך הדין לגבי חובת דיווח לרשות להגנת הפרטיות.</div>\n<div class=\"card warn\"><b>איבדתי גם את הטלגרם וגם את המכשיר של Ops:</b> 1) מתחברים ל-Ops ממחשב חדש עם הסיסמה. את המכשיר החדש מאשרים עם הקוד שמגיע למייל הראשי, או עם קוד שחזור מודפס. 2) פותחים חשבון טלגרם חדש (או משחזרים את הקיים במספר הטלפון) ושולחים לגדעון הודעה. גדעון שולח קוד חד-פעמי למייל הראשי. מקלידים אותו בצ'אט תוך 10 דקות, ויש 3 ניסיונות. 3) אפשרות נוספת: ב-Ops ← גדעון ← אבטחה ← \"חשבונות טלגרם נוספים\" לוחצים \"זה אני, אשר\" ומאמתים עם אפליקציית קודים או קוד גיבוי. 4) אם החשבון נחסם, משחררים את החסימה באותו מסך ושולחים הודעה שוב. 5) כדי שהחשבון החדש יהיה גם הראשי (כולל Face ID בטלגרם), מפתח מעדכן ב-Vercel את <code>CEO_TELEGRAM_ALLOWED_CHAT_IDS</code> למספר החדש ומעלה גרסה. 6) ב-Ops רושמים מחדש Face ID ומסירים את המכשירים הישנים. אם גם המייל הראשי אבד, משחזרים אותו קודם דרך Google.</div>\n<div class=\"card\"><b>מפתחות ההצפנה אבדו:</b> פותחים את \"מדריך גיבוי ושחזור המפתחות\" ופועלים לפי שלב 4.</div>\n\n<h2><span class=\"n\">3</span>שחזור מסד הנתונים מהגיבוי הלילי</h2>\n<div class=\"card\"><b>מה צריך:</b> מחשב עם Postgres 17 ועם הכלי age, את מפתח פתיחת הגיבוי (נמצא בגיבוי המפתחות בשם <code>DB_BACKUP_AGE_IDENTITY</code>), ואת כתובת החיבור של מסד הנתונים שמשחזרים אליו.</div>\n<ol class=\"card\">\n<li>ב-Cloudflare, באחסון הקבצים R2, נכנסים לתיקייה <code>backups/db/</code> ומורידים את הקובץ האחרון שמסתיים ב-<code>.dump.age</code>, ואת קובץ ה-<code>.sha256</code> שלידו, לאותה תיקייה.</li>\n<li>שומרים את מפתח הפתיחה בקובץ <code>identity.txt</code> באותה תיקייה.</li>\n<li>אם מסד הנתונים נמחק לגמרי: פותחים פרויקט חדש ב-Supabase באירופה, ובמסך Connect מעתיקים את כתובת החיבור הישירה (Direct connection).</li>\n<li>מריצים מתיקיית הקוד:<br><code>AGE_IDENTITY_FILE=identity.txt TARGET_DATABASE_URL='כתובת-החיבור' bash scripts/backup/db-restore.sh nurawell-db-….dump.age</code><br>הפקודה בודקת קודם שהקובץ שלם (שורה שמסתיימת ב-OK), ורק אחר כך משחזרת.</li>\n<li>הודעות על דברים \"שכבר קיימים\" בפרויקט Supabase חדש הן תקינות. בודקים במסך Table Editor שיש משתמשים והודעות.</li>\n<li>בפרויקט חדש: מעדכנים ב-Vercel את משתני הסביבה של Supabase (כתובת ומפתחות) ומעלים מחדש. מפתחות ההצפנה לא משתנים, ולכן המידע המוצפן נפתח כרגיל.</li>\n<li>מוחקים את <code>identity.txt</code> מהמחשב בסיום.</li>\n</ol>\n\n<h2><span class=\"n\">4</span>למי פונים</h2>\n<table>\n<tr><td><b>הבעלים</b></td><td>דניאל רחמן · danielsbhaucc@gmail.com</td></tr>\n<tr><td><b>עורך הדין</b></td><td>מחזיק בחלק שחזור 3. שם ומספר: ____________________</td></tr>\n<tr><td><b>מפתח גיבוי</b></td><td>שם ומספר: ____________________</td></tr>\n<tr><td><b>תמיכה של השירותים</b></td><td>vercel.com/help · supabase.com/support · dash.cloudflare.com (Support) · resend.com/support · github.com/contact</td></tr>\n</table>\n<div class=\"foot\">NuraWell · מסמך פנימי · עודכן ב-{{DATE}}</div>\n</div></body></html>\n";
